def sum_values(d):
    total = 0
    for v in d.values():
        total += v
    return total

print(sum_values({"a": 1, "b": 2, "c": 3}))  # output: 6

def invert_dict(d):
    result = {}
    for k, v in d.items():
        result[v] = k
    return result

print(invert_dict({"a": 1, "b": 2}))  # output: {1: 'a', 2: 'b'}

def word_frequencies(words):
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return freq

print(word_frequencies(["a", "b", "a"]))  # output: {'a': 2, 'b': 1}

def max_key(d):
    best_key = None
    best_val = float("-inf")
    for k, v in d.items():
        if v > best_val:
            best_val = v
            best_key = k
    return best_key

print(max_key({"a": 3, "b": 9, "c": 5}))  # output: b

def get_value(d, key, default=None):
    if key in d:
        return d[key]
    return default

print(get_value({"a": 1}, "a"))       # output: 1
print(get_value({"a": 1}, "z", 0))    # output: 0

def merge_dicts(a, b):
    result = {}
    result.update(a)
    result.update(b)
    return result

print(merge_dicts({"a": 1}, {"b": 2}))  # output: {'a': 1, 'b': 2}

def sort_by_value(d):
    items = list(d.items())
    items.sort(key=lambda x: x[1])
    return dict(items)

print(sort_by_value({"a": 3, "b": 1, "c": 2}))  # output: {'b': 1, 'c': 2, 'a': 3}

def keys_above(d, threshold):
    result = []
    for k, v in d.items():
        if v > threshold:
            result.append(k)
    return result

print(keys_above({"a": 5, "b": 15, "c": 8}, 10))  # output: ['b']

def top_student(marks):
    top = None
    best = -1
    for name, score in marks.items():
        if score > best:
            best = score
            top = name
    return top, best

print(top_student({"Ravi": 78, "Meena": 92, "Amit": 85}))  # output: ('Meena', 92)
